# Preserve all stable checklist items. Unassessed items remain unknown.
checklist=load('references/stamped/checklist/stamped-checklist.json'); answers={}
known={'must/001':('demonstrated','Study components nested under working root; runtime referenced explicitly.'),'must/002':('demonstrated','Input subdataset, scripts and environment specification share root.'),'must/007':('demonstrated','README.md supplies executable usage and requirements.'),'must/008':('demonstrated','code/replay.sh executed and derivative digests matched in fresh workspace.'),'must/009':('demonstrated','Analysis uses CLI arguments and relative paths; fresh directory replay passed.'),'must/010':('demonstrated','Analysis uses Python standard library; Python declared in pixi.toml.'),'must/011':('partial','Named host and Python version recorded; no other platform tested.'),'must/012':('demonstrated','README.md and reports/environment.json give analysis requirements.'),'should/003':('demonstrated','Raw subdataset, code, derivative results and reports separated.'),'should/004':('partial','Fresh local venv/workspace replay passed; shared OS and interpreter.'),'should/005':('partial','Verification constructs disposable venv; ordinary replay uses existing runtime.'),'may/001':('demonstrated','inputs/ds000005 is an independently pinned Git subdataset.'),'may/002':('demonstrated','README.md documents module boundaries and CLI interfaces.'),'may/005':('demonstrated','README.md and report link the analysis and outputs.')}
for level in checklist['data']:
    for entry in level['entries']:
        for item in entry['items']:
            key=item['id'].split(':')[1]; status,reason=known.get(key,('unknown','Not assessed at item-specific scope in this bounded offline run.'))
            answers[item['id']]={'status':status,'reason':reason}
save('reports/checklist_answers.json',{'checklist_version':checklist['checklist_version'],'items':answers})
readroot=Path('/Users/johnlee/code/CON/stamped-ai-research/skills'); skill_names=['align-with-stamped-principles','assess-alignment-with-stamped-principles','create-repronim-stamped-project','create-stamped-project','do-full-research-loop']
applications=['Baseline in protocol; scoped executable improvements; evidence-based reassessment.','Seven-property evidence table and portable JSON assessment; complete checklist side product.','Pinned DataLad subdataset, source attribution, BIDS declaration, raw/derivative boundary; no imaging pipeline.','Explicit object boundary, component manifest, stdlib entrypoint, existing environment and disposable replay.','Protocol before computation; completed analysis, independent checks, replay, limitations and report.']
usage=[]
for name,app in zip(skill_names,applications):
    tree=readroot/name
    files=[{'path':str(f.relative_to(tree)),'sha256':sha(f)} for f in sorted(tree.rglob('*')) if f.is_file()]
    reads=['SKILL.md','references/principles.md']
